import crypto from "node:crypto";
import { type BareRepo, git } from "./git-fixture";
import { manifest } from "./profiles";

/**
 * Committed file trees for repository preview tests. Eligibility tests read
 * the fact documents the pinned bundle produces for them; preparation tests
 * commit them to fixture remotes.
 */

export type Tree = Readonly<Record<string, string>>;

const npmLock = (name: string, workspaces?: string[]) => manifest({ name, lockfileVersion: 3, requires: true, packages: { "": { name, ...(workspaces && { workspaces }) } } });
const pnpmLock = "lockfileVersion: '9.0'\n\nimporters:\n\n  .: {}\n";

