/**
 * A stand-in for Vite's command line: `vite build` writes dist/index.html and
 * its script under the base path `--base=` gives, as Vite does. It fails like
 * a compiler when src/main.js holds `SYNTAX ERROR`, and ignores the base path
 * when fixture.json sets ignoreBase. The JSON file fixture.json's `control`
 * names, which a test writes, holds the build while it has `"hold": true`
 * and fails it with `"fail": true`.
 */
const FAKE_VITE = `#!/usr/bin/env node
import fs from "node:fs";
const settings = fs.existsSync("fixture.json") ? JSON.parse(fs.readFileSync("fixture.json", "utf8")) : {};
const control = () => (settings.control && fs.existsSync(settings.control) ? JSON.parse(fs.readFileSync(settings.control, "utf8")) : {});
const given = process.argv.find((arg) => arg.startsWith("--base="))?.slice(7) ?? "/";
const base = settings.ignoreBase ? "/" : given;
console.log("vite v5.4.0 building for production...");
while (control().hold) await new Promise((resolve) => setTimeout(resolve, 50));
const source = fs.readFileSync("src/main.js", "utf8");
if (source.includes("SYNTAX ERROR") || control().fail) {
  console.error("[vite:build] src/main.js (1:7): Unexpected token");
  console.error("error during build: SyntaxError: Unexpected token");
  process.exit(1);
}
fs.mkdirSync("dist/assets", { recursive: true });
fs.writeFileSync("dist/assets/index.js", source);
fs.writeFileSync("dist/index.html", fs.readFileSync("index.html", "utf8").replace('src="/src/main.js"', 'src="' + base + 'assets/index.js"'));
console.log("dist/index.html");
console.log("dist/assets/index.js");
console.log("built in 12ms");
`;

/**
 * A Vite React application that installs and builds offline: React and Vite
 * are local packages its npm lockfile links from vendor/, and its Vite is
 * FAKE_VITE, so `npm ci` needs no registry and a build takes milliseconds.
 * Its page shows +heading+ and the route it's at. +settings+ becomes
 * fixture.json; +broken+ makes the build fail.
 */
export function offlineViteApp(options: { heading?: string; broken?: boolean; settings?: Record<string, unknown> } = {}): Tree {
  const dependencies = { react: "file:vendor/react" };
  const devDependencies = { vite: "file:vendor/vite" };
  const heading = JSON.stringify(options.heading ?? "Orders");
  return {
    "package.json": manifest({ name: "orders-web", version: "1.0.0", private: true, type: "module", scripts: { build: "vite build" }, dependencies, devDependencies }),
    "package-lock.json": manifest({
      name: "orders-web",
      version: "1.0.0",
      lockfileVersion: 3,
      requires: true,
      packages: {
        "": { name: "orders-web", version: "1.0.0", dependencies, devDependencies },
        "node_modules/react": { resolved: "vendor/react", link: true },
        "node_modules/vite": { resolved: "vendor/vite", dev: true, link: true },
        "vendor/react": { name: "react", version: "18.3.1" },
        "vendor/vite": { name: "vite", version: "5.4.0", dev: true, bin: { vite: "bin/vite.js" } },
      },
    }),
    "vite.config.js": "export default {};\n",
    "index.html": '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><title>Orders</title></head><body><main id="root"></main><script type="module" src="/src/main.js"></script></body></html>\n',
    "src/main.js": `${options.broken ? "SYNTAX ERROR\n" : ""}document.getElementById("root").innerHTML = "<h1>" + ${heading} + "</h1><p data-route>" + location.pathname + "</p>";\n`,
    "fixture.json": `${JSON.stringify(options.settings ?? {})}\n`,
    "vendor/react/package.json": manifest({ name: "react", version: "18.3.1", main: "index.js" }),
    "vendor/react/index.js": "export const version = '18.3.1';\n",
    "vendor/vite/package.json": manifest({ name: "vite", version: "5.4.0", type: "module", bin: { vite: "bin/vite.js" } }),
    "vendor/vite/bin/vite.js": FAKE_VITE,
  };
}

/** An npm lockfile that links each of +links+ (package name to its vendor/ directory) for the root package +name+. */
function linkedLock(name: string, dependencies: Record<string, string>, devDependencies: Record<string, string>, vendored: Record<string, { name: string; version: string; dev?: boolean; bin?: Record<string, string> }>): string {
  const packages: Record<string, unknown> = { "": { name, version: "1.0.0", dependencies, devDependencies } };
  for (const [directory, vendor] of Object.entries(vendored)) {
    packages[`node_modules/${vendor.name}`] = { resolved: directory, link: true, ...(vendor.dev && { dev: true }) };
    packages[directory] = { name: vendor.name, version: vendor.version, ...(vendor.dev && { dev: true }), ...(vendor.bin && { bin: vendor.bin }) };
  }
  return manifest({ name, version: "1.0.0", lockfileVersion: 3, requires: true, packages });
}

/**
 * A stand-in for Rspack's command line building a Module Federation remote
 * with a page of its own, as fleet/mf-admin's HtmlRspackPlugin does: it
 * writes dist/remoteEntry.js, a container with the V1 protocol (`init` and
 * `get`) whose exposed modules are chunks loaded beside the entry, as
 * `publicPath: "auto"` does, and dist/index.html with main.js, the remote's
 * own bootstrap, which renders ./Header from its container into the page.
 */
const FAKE_RSPACK = `#!/usr/bin/env node
import fs from "node:fs";
const settings = JSON.parse(fs.readFileSync("fixture.json", "utf8"));
console.log("Rspack building " + settings.container + "...");
fs.mkdirSync("dist", { recursive: true });
const chunks = {};
for (const [expose, source] of Object.entries(settings.exposes)) {
  const chunk = expose.replace(/^\\.\\//, "").toLowerCase() + ".js";
  const factory = fs.readFileSync(source, "utf8").replace("export default function", "function");
  fs.writeFileSync("dist/" + chunk, "(self." + settings.container + "Chunks = self." + settings.container + "Chunks || {})[" + JSON.stringify(expose) + "] = " + factory);
  chunks[expose] = chunk;
}
fs.writeFileSync("dist/remoteEntry.js", \`var \${settings.container};
(function () {
  "use strict";
  var base = document.currentScript.src.replace(/[^/]*$/, "");
  var chunks = \${JSON.stringify(chunks)};
  function load(chunk) {
    return new Promise(function (resolve, reject) {
      var script = document.createElement("script");
      script.src = base + chunk;
      script.onload = resolve;
      script.onerror = function () { reject(new Error("Loading chunk " + chunk + " failed.")); };
      document.head.appendChild(script);
    });
  }
  \${settings.container} = {
    init: function () { return Promise.resolve(); },
    get: function (module) {
      if (!Object.prototype.hasOwnProperty.call(chunks, module)) return Promise.reject(new Error('Module "' + module + '" does not exist in container.'));
      return load(chunks[module]).then(function () {
        var render = self.\${settings.container}Chunks[module];
        return function () { return { default: render }; };
      });
    }
  };
})();
\`);
fs.writeFileSync("dist/main.js", settings.container + '.init({}).then(function () { return ' + settings.container + '.get("./Header"); }).then(function (factory) { factory().default(document.getElementById("root")); });\\n');
fs.writeFileSync("dist/index.html", '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Admin remote</title><script defer src="remoteEntry.js"></script><script defer src="main.js"></script></head><body><main id="root"></main></body></html>\\n');
console.log("dist/index.html");
console.log("dist/remoteEntry.js");
`;

/**
 * A Module Federation remote, `fixtureAdmin`, that installs and builds
 * offline like offlineViteApp, its Rspack's command line FAKE_RSPACK, linked
 * from vendor/. It exposes ./Footer and ./Header, and its build emits a page
 * of its own that renders ./Header from its container, so it previews like
 * any other application. Its rspack.config.cjs is what the Profile reads;
 * the build never loads it.
 */
export function offlineFederatedRemote(): Tree {
  const dependencies = { react: "file:vendor/react" };
  const devDependencies = { "@rspack/cli": "file:vendor/rspack-cli" };
  const exposes = { "./Header": "./src/Header.js", "./Footer": "./src/Footer.js" };
  const exposed = (heading: string) => `export default function render(element) {\n  element.innerHTML = "<h1>${heading}</h1><p data-route>" + location.pathname + "</p>";\n}\n`;
  return {
    "package.json": manifest({ name: "admin-remote", version: "1.0.0", private: true, scripts: { build: "rspack build" }, dependencies, devDependencies }),
    "package-lock.json": linkedLock("admin-remote", dependencies, devDependencies, {
      "vendor/react": { name: "react", version: "18.3.1" },
      "vendor/rspack-cli": { name: "@rspack/cli", version: "1.1.0", dev: true, bin: { rspack: "bin/rspack.js" } },
    }),
    "rspack.config.cjs": `const path = require("node:path");\nconst rspack = require("@rspack/core");\nmodule.exports = {\n  output: { path: path.resolve(__dirname, "dist"), publicPath: "auto" },\n  plugins: [\n    new rspack.container.ModuleFederationPlugin({\n      name: "fixtureAdmin",\n      filename: "remoteEntry.js",\n      exposes: ${JSON.stringify(exposes)},\n      shared: { react: { singleton: true } },\n    }),\n    new rspack.HtmlRspackPlugin({ template: path.resolve(__dirname, "src/index.html") }),\n  ],\n};\n`,
    "src/index.html": '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><title>Admin remote</title></head><body><main id="root"></main></body></html>\n',
    "src/Header.js": exposed("Admin header"),
    "src/Footer.js": exposed("Admin footer"),
    "fixture.json": `${JSON.stringify({ container: "fixtureAdmin", exposes })}\n`,
    "vendor/react/package.json": manifest({ name: "react", version: "18.3.1", main: "index.js" }),
    "vendor/react/index.js": "export const version = '18.3.1';\n",
    "vendor/rspack-cli/package.json": manifest({ name: "@rspack/cli", version: "1.1.0", type: "module", bin: { rspack: "bin/rspack.js" } }),
    "vendor/rspack-cli/bin/rspack.js": FAKE_RSPACK,
  };
}

/** single-spa lifecycles for React left external, as fleet/spa-orders's are: the source the Profile reads for a single-spa application. */
const LIFECYCLES =
  'import React from "react";\nimport { createRoot } from "react-dom/client";\n\nconst roots = {};\n\nexport function bootstrap() {\n  return Promise.resolve();\n}\n\nexport function mount(props) {\n  roots[props.name] = createRoot(props.domElement);\n  roots[props.name].render(React.createElement("h1", null, "Orders"));\n  return Promise.resolve();\n}\n\nexport function unmount(props) {\n  roots[props.name].unmount();\n  return Promise.resolve();\n}\n';

/**
 * A stand-in for webpack's command line building a single-spa application's
 * lifecycles as one System.register bundle with React left external, and no
 * page: dist/orders.js alone.
 */
const FAKE_WEBPACK = `#!/usr/bin/env node
import fs from "node:fs";
console.log("webpack 5.90.0 compiling...");
fs.mkdirSync("dist", { recursive: true });
fs.writeFileSync("dist/orders.js", 'System.register(["react", "react-dom/client"], function (exports) {\\n  var React, createRoot;\\n  return {\\n    setters: [function (module) { React = module.default; }, function (module) { createRoot = module.createRoot; }],\\n    execute: function () {\\n      var roots = {};\\n      exports({\\n        bootstrap: function () { return Promise.resolve(); },\\n        mount: function (props) { roots[props.name] = createRoot(props.domElement); roots[props.name].render(React.createElement("h1", null, "Orders")); return Promise.resolve(); },\\n        unmount: function (props) { roots[props.name].unmount(); return Promise.resolve(); }\\n      });\\n    }\\n  };\\n});\\n');
console.log("dist/orders.js");
`;

/**
 * A single-spa application, like fleet/spa-reports, built with webpack, that
 * installs and builds offline like offlineViteApp, its webpack FAKE_WEBPACK.
 * Its configuration adds no HTML plugin, so preparation refuses it for its
 * page. With +configAt+ elsewhere than where webpack looks by default, which
 * its build script names, preparation can't tell, so it builds: the build
 * succeeds but emits only a lifecycle bundle, no page, so nothing can be
 * published.
 */
export function offlineSingleSpaBundle(options: { configAt?: string } = {}): Tree {
  const dependencies = { react: "file:vendor/react" };
  const devDependencies = { webpack: "file:vendor/webpack" };
  const configAt = options.configAt ?? "webpack.config.js";
  return {
    "package.json": manifest({ name: "orders-spa", version: "1.0.0", private: true, scripts: { build: configAt === "webpack.config.js" ? "webpack" : `webpack --config ${configAt}` }, dependencies, devDependencies }),
    "package-lock.json": linkedLock("orders-spa", dependencies, devDependencies, {
      "vendor/react": { name: "react", version: "18.3.1" },
      "vendor/webpack": { name: "webpack", version: "5.90.0", dev: true, bin: { webpack: "bin/webpack.js" } },
    }),
    [configAt]: 'const path = require("node:path");\nmodule.exports = {\n  entry: "./src/lifecycles.js",\n  output: { path: path.resolve(__dirname, "dist"), filename: "orders.js", libraryTarget: "system" },\n  externals: ["react", "react-dom", "react-dom/client"],\n};\n',
    "src/lifecycles.js": LIFECYCLES,
    "vendor/react/package.json": manifest({ name: "react", version: "18.3.1", main: "index.js" }),
    "vendor/react/index.js": "export const version = '18.3.1';\n",
    "vendor/webpack/package.json": manifest({ name: "webpack", version: "5.90.0", type: "module", bin: { webpack: "bin/webpack.js" } }),
    "vendor/webpack/bin/webpack.js": FAKE_WEBPACK,
  };
}

/**
 * A single-spa application built as a Vite library, as fleet/spa-orders is:
 * its configuration's input is its lifecycles, with React left external, and
 * no index.html is committed, so Vite would build no page. Everything else
 * qualifies, offline, as in offlineViteApp.
 */
export function offlineViteLibrary(): Tree {
  const dependencies = { react: "file:vendor/react" };
  const devDependencies = { vite: "file:vendor/vite" };
  return {
    "package.json": manifest({ name: "orders-spa", version: "1.0.0", private: true, type: "module", scripts: { build: "vite build" }, dependencies, devDependencies }),
    "package-lock.json": linkedLock("orders-spa", dependencies, devDependencies, {
      "vendor/react": { name: "react", version: "18.3.1" },
      "vendor/vite": { name: "vite", version: "5.4.0", dev: true, bin: { vite: "bin/vite.js" } },
    }),
    "vite.config.js":
      'export default {\n  build: {\n    rollupOptions: {\n      input: "src/lifecycles.js",\n      external: ["react", "react-dom", "react-dom/client"],\n      output: { format: "system", entryFileNames: "assets/orders.js" },\n    },\n  },\n};\n',
    "src/lifecycles.js": LIFECYCLES,
    "vendor/react/package.json": manifest({ name: "react", version: "18.3.1", main: "index.js" }),
    "vendor/react/index.js": "export const version = '18.3.1';\n",
    "vendor/vite/package.json": manifest({ name: "vite", version: "5.4.0", type: "module", bin: { vite: "bin/vite.js" } }),
    "vendor/vite/bin/vite.js": FAKE_VITE,
  };
}

/** Two commits in +remote+ whose SHAs share their first +length+ characters, written with stable content. */
export function collidingCommits(remote: BareRepo, length: number): [string, string] {
  const tree = git(remote.path, ["mktree"], { input: "" }).trim();
  const seen = new Map<string, string>();
  for (let index = 0; ; index++) {
    const body = `tree ${tree}\nauthor Fixture <fixture@example.com> 1767225600 +0000\ncommitter Fixture <fixture@example.com> 1767225600 +0000\n\ncollision ${index}\n`;
    const sha = crypto.createHash("sha1").update(`commit ${Buffer.byteLength(body)}\0${body}`).digest("hex");
    const other = seen.get(sha.slice(0, length));
    if (other !== undefined) {
      const write = (content: string) => git(remote.path, ["hash-object", "-t", "commit", "-w", "--stdin"], { input: content }).trim();
      const left = write(other);
      const right = write(body);
      if (left.slice(0, length) !== right.slice(0, length)) throw new Error("The commits don't collide");
      return [left, right];
    }
    seen.set(sha.slice(0, length), body);
  }
}
